<span class="line"><span style="color:#61AFEF;">        assert_eq!</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">r2</span><span style="color:#ABB2BF;">.path, </span><span style="color:#98C379;">&quot;/b&quot;</span><span style="color:#ABB2BF;">);</span></span>
